CREATE DATABASE IF NOT EXISTS estatepro CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE estatepro;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(30),role ENUM('admin','agent','customer') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_users_role(role));
CREATE TABLE IF NOT EXISTS agents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,license_number VARCHAR(80),bio TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS properties (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,property_type ENUM('Apartment','Villa','House','Plot','Commercial') NOT NULL,listing_type ENUM('sale','rent') NOT NULL,price DECIMAL(15,2) NOT NULL,address VARCHAR(255) NOT NULL,city VARCHAR(100) NOT NULL,state VARCHAR(100) NOT NULL,bedrooms SMALLINT UNSIGNED DEFAULT 0,bathrooms SMALLINT UNSIGNED DEFAULT 0,area_sqft DECIMAL(12,2),agent_id BIGINT UNSIGNED,status ENUM('draft','published','sold','rented','archived') DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(agent_id) REFERENCES agents(id) ON DELETE SET NULL,INDEX idx_property_search(city,property_type,listing_type,status),INDEX idx_property_price(price));
CREATE TABLE IF NOT EXISTS property_images(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id BIGINT UNSIGNED NOT NULL,image_url VARCHAR(500) NOT NULL,alt_text VARCHAR(255),sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,INDEX idx_images_property(property_id));
CREATE TABLE IF NOT EXISTS amenities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS property_amenities(property_id BIGINT UNSIGNED NOT NULL,amenity_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(property_id,amenity_id),FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,FOREIGN KEY(amenity_id) REFERENCES amenities(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS enquiries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,agent_id BIGINT UNSIGNED,message TEXT,status ENUM('new','contacted','qualified','closed') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(agent_id) REFERENCES agents(id) ON DELETE SET NULL,INDEX idx_enquiry_status(status),INDEX idx_enquiry_agent(agent_id));
CREATE TABLE IF NOT EXISTS appointments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,agent_id BIGINT UNSIGNED,scheduled_at DATETIME NOT NULL,status ENUM('scheduled','confirmed','completed','cancelled') DEFAULT 'scheduled',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(agent_id) REFERENCES agents(id) ON DELETE SET NULL,INDEX idx_appointments_time(scheduled_at),INDEX idx_appointments_agent(agent_id));
CREATE TABLE IF NOT EXISTS saved_properties(user_id BIGINT UNSIGNED NOT NULL,property_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,property_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE);
